class Dog:
    def speak(self):
        return "Woof"

class Cat:
    def speak(self):
        return "Meow"

def animal_factory(kind):
    animals = {"dog": Dog, "cat": Cat}
    return animals[kind]()

for kind in ["dog", "cat"]:
    animal = animal_factory(kind)
    print(f"{kind}: {animal.speak()}")
